<?php
declare(strict_types=1);
$sql=[
"CREATE TABLE svc_inspections (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,service_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,service_version BIGINT UNSIGNED NOT NULL,actor_id VARCHAR(64) CHARACTER SET ascii NOT NULL,found BOOLEAN NOT NULL,evidence_encrypted LONGTEXT NOT NULL,fingerprint CHAR(64) CHARACTER SET ascii NOT NULL,expires_at DATETIME(6) NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),KEY ix_svc_inspect(service_id,created_at,id),FOREIGN KEY(operation_id) REFERENCES svc_operations(id)) ENGINE=InnoDB",
"CREATE TABLE svc_resolutions (id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,service_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,operation_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,inspection_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,actor_id VARCHAR(64) CHARACTER SET ascii NOT NULL,trace_id CHAR(36) CHARACTER SET ascii NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),FOREIGN KEY(operation_id) REFERENCES svc_operations(id),FOREIGN KEY(inspection_id) REFERENCES svc_inspections(id)) ENGINE=InnoDB",
];foreach(['svc_inspections','svc_resolutions'] as $table){foreach(['UPDATE','DELETE'] as $verb){$sql[]="CREATE TRIGGER {$table}_".strtolower($verb)." BEFORE $verb ON $table FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable provider reconciliation'";}}return $sql;
